import{_ as r,o as s,c as o,a2 as a}from"./chunks/framework.BXzK3EA4.js";const n="/assets/%E7%8B%AC%E6%9C%8D%E5%BC%80%E6%9C%BA.0doa6jhf.png",e="/assets/%E7%8B%AC%E6%9C%8D%E5%85%B3%E6%9C%BA.CPc0xKFU.png",p="/assets/%E7%8B%AC%E6%9C%8D%E9%87%8D%E5%90%AF.BDf6GeGl.png",i="/assets/%E7%8B%AC%E6%9C%8D%E9%87%8D%E7%BD%AEbmc.DbtmEXep.png",l="/assets/%E7%8B%AC%E6%9C%8D%E6%95%91%E6%8F%B4%E7%B3%BB%E7%BB%9F.DCLvrP8b.png",g="/assets/%E9%80%89%E6%8B%A9%E6%95%91%E6%8F%B4%E7%B3%BB%E7%BB%9F.Cyypm9oi.png",c="/assets/%E7%8B%AC%E6%9C%8D%E7%A0%B4%E8%A7%A3%E5%AF%86%E7%A0%8111.DTy4v6Ve.png",E="/assets/%E8%87%AA%E5%8A%A8%E7%A0%B4%E8%A7%A311.K_fFpSSb.png",h="/assets/%E8%87%AA%E5%AE%9A%E4%B9%89%E5%AF%86%E7%A0%81.D_IEyGsQ.png",d="/assets/%E7%8B%AC%E6%9C%8D%E9%87%8D%E8%A3%85%E7%B3%BB%E7%BB%9F.CkKyLXVV.png",m="/assets/%E7%8B%AC%E6%9C%8D%E9%87%8D%E8%A3%85%E7%B3%BB%E7%BB%9F%E9%80%89%E6%8B%A911.Dq7veBn5.png",q=JSON.parse('{"title":"执行服务器操作","description":"","frontmatter":{"title":"执行服务器操作"},"headers":[],"relativePath":"dedicatedserver/manage-servers/server-operations.md","filePath":"dedicatedserver/manage-servers/server-operations.md","lastUpdated":1788259091000}'),B={name:"dedicatedserver/manage-servers/server-operations.md"};function _(A,t,C,b,u,D){return s(),o("div",null,[...t[0]||(t[0]=[a('<p>在物理服务器<strong>管理产品</strong>页面，支持开机、关机、重启、重置 BMC、使用 VNC、救援系统、破解密码和重装系统等操作。</p><hr><h3 id="开机" tabindex="-1">开机 <a class="header-anchor" href="#开机" aria-label="Permalink to &quot;开机&quot;">​</a></h3><p>物理服务器开机是指启动已关机的服务器。</p><ol><li><p>在物理服务器管理产品-&gt;管理面板，单击<strong>开机</strong>。</p><p><img src="'+n+'" alt="独服开机.png"></p></li><li><p>在<strong>开机</strong>确认页面单击<strong>确认</strong>。</p></li></ol><hr><h3 id="关机" tabindex="-1">关机 <a class="header-anchor" href="#关机" aria-label="Permalink to &quot;关机&quot;">​</a></h3><p>物理服务器关机是指关闭运行中的服务器。建议先通过远程连接保存数据。</p><ol><li><p>在物理服务器管理产品-&gt;管理面板，单击<strong>关机</strong>。</p><p><img src="'+e+'" alt="独服关机.png"></p></li><li><p>在<strong>关机</strong>确认页面单击<strong>确认</strong>。</p></li></ol><hr><h3 id="重启" tabindex="-1">重启 <a class="header-anchor" href="#重启" aria-label="Permalink to &quot;重启&quot;">​</a></h3><p>物理服务器重启是指将运行中的服务器关机并重新开机。适用于系统卡顿、配置生效等场景。</p><ol><li><p>在物理服务器管理产品-&gt;管理面板，单击<strong>重启</strong>。</p><p><img src="'+p+'" alt="独服重启.png"></p></li><li><p>在<strong>重启</strong>确认页面单击<strong>确认</strong>。</p></li></ol><hr><h3 id="重置-bmc" tabindex="-1">重置 BMC <a class="header-anchor" href="#重置-bmc" aria-label="Permalink to &quot;重置 BMC&quot;">​</a></h3><p>重置 BMC 是指重置物理服务器管理控制器，解决远程管理相关故障。</p><ol><li><p>在物理服务器管理产品-&gt;管理面板，单击<strong>重置BMC</strong>。</p><p><img src="'+i+'" alt="独服重置bmc.png"></p></li><li><p>在<strong>重置 BMC</strong>确认页面单击<strong>确认</strong>。</p></li></ol><hr><h3 id="使用-vnc" tabindex="-1">使用 VNC <a class="header-anchor" href="#使用-vnc" aria-label="Permalink to &quot;使用 VNC&quot;">​</a></h3><p>使用 VNC 是指通过 VNC 远程连接物理服务器控制台。无需网络配置，直接访问系统界面。关于如何连接物理服务器的方法可参考<a href="/dedicatedserver/quickstart/login.html">登录物理服务器</a>。</p><hr><h3 id="救援系统" tabindex="-1">救援系统 <a class="header-anchor" href="#救援系统" aria-label="Permalink to &quot;救援系统&quot;">​</a></h3><p>救援系统是指启动救援模式。用于系统故障、密码找回等紧急场景。</p><ol><li><p>在物理服务器<strong>管理产品</strong>页面，单击<strong>救援系统</strong>。</p><p><img src="'+l+'" alt="独服救援系统.png"></p></li><li><p>选择<strong>操作系统</strong>，单击<strong>确认</strong>。</p><p><img src="'+g+'" alt="选择救援系统.png"></p></li></ol><hr><h3 id="破解密码" tabindex="-1">破解密码 <a class="header-anchor" href="#破解密码" aria-label="Permalink to &quot;破解密码&quot;">​</a></h3><p>破解密码是指重置物理服务器系统登录密码。</p><ol><li><p>在物理服务器<strong>管理产品</strong>页面，单击<strong>破解密码</strong>。</p><p><img src="'+c+'" alt="独服破解密码11.png"></p></li><li><p>在<strong>破解密码</strong>页面，系统将会默认破解 Administrator/root 用户的密码，单击<strong>确认</strong>。</p><p><img src="'+E+'" alt="自动破解11.png"></p></li><li><p>（可选）在<strong>破解密码</strong>页面，勾选<strong>选择后将会破解自定义的用户的密码</strong>，输入<strong>自定义用户</strong>，单击<strong>确认</strong>。</p><p><img src="'+h+'" alt="自定义密码.png"></p></li></ol><hr><h3 id="重装系统" tabindex="-1">重装系统 <a class="header-anchor" href="#重装系统" aria-label="Permalink to &quot;重装系统&quot;">​</a></h3><p>重装系统是指重新部署操作系统镜像，将物理服务器系统盘恢复至初始状态，常用于系统故障、更换系统版本或清理环境等场景，操作会格式化系统盘（数据盘通常不受影响，视配置而定）。</p><blockquote><p><strong>注意</strong></p><p>重装会清除系统盘数据，请提前备份。</p></blockquote><ol><li><p>在物理服务器管理产品-&gt;管理面板，单击<strong>重装系统</strong>。</p><p><img src="'+d+'" alt="独服重装系统.png"></p></li><li><p>在<strong>重装系统</strong>页面，根据提示完成操作系统、密码、端口等信息的选择和输入。</p><p><img src="'+m+'" alt="独服重装系统选择11.png"></p></li><li><p>单击<strong>确认重装</strong>。</p></li></ol>',33)])])}const v=r(B,[["render",_]]);export{q as __pageData,v as default};
